import React from 'react';
import { useAppState } from '../../contexts/AppContext';

const ProtectedRoute = ({ children }) => {
  const { user } = useAppState();

  // Simple auth check - in a real app, this would be more sophisticated
  if (!user.isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-kali-dark">
        <div className="text-center">
          <div className="mb-8">
            <div className="w-24 h-24 mx-auto mb-4 bg-kali-green/20 rounded-full flex items-center justify-center">
              <svg className="w-12 h-12 text-kali-green" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <h1 className="text-2xl font-bold text-white mb-2">Access Denied</h1>
            <p className="text-kali-gray-400">Authentication required to access Kali Dashboard</p>
          </div>
          <button 
            className="btn-primary"
            onClick={() => {
              // Mock login - in real app, this would redirect to login
              window.location.reload();
            }}
          >
            Authenticate
          </button>
        </div>
      </div>
    );
  }

  return children;
};

export default ProtectedRoute;
